#pragma once
// Palette entries for the Particles v2 nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendParticlesNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphParticlesNodeTable.cs pin for pin
// (docs/plans/wave10/GPU_PARTICLES.md section 2.13). Effect paths and user-parameter names are attributes, never pins;
// entities are ints. The four older emitter nodes (Set Emitter Enabled, Set Emitter Effect, Restart Emitter, Spawn
// Emitter At) live in GraphNodeDefsRenderProps.hpp and keep their keys; nothing here duplicates them.

inline void appendParticlesNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_SpawnParticlesAt", "Spawn Particles At", "Particles", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("dirX", "float", false, "0"), pin("dirY", "float", false, "0"), pin("dirZ", "float", false, "1"),
        pin("count", "int", false, "1"), pin("then", "exec", true), pin("spawned", "int", true)},
        {attr("effect", "Particle effect (.ocparticle)")}});
    t.push_back({"AN_SetParticleFloat", "Set Particle Float", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("value", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("param", "User parameter name")}});
    t.push_back({"AN_SetParticleVector", "Set Particle Vector", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("param", "User parameter name")}});
    t.push_back({"AN_SetParticleColor", "Set Particle Color", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("r", "float", false), pin("g", "float", false), pin("b", "float", false),
        pin("a", "float", false, "1"), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("param", "User parameter name")}});
    t.push_back({"AN_BurstEmitter", "Burst Emitter", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("count", "int", false, "10"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_StopEmitter", "Stop Emitter", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("killParticles", "bool", false, "false"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_SetEmitterModifiers", "Set Emitter Modifiers", "Particles", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("rateScale", "float", false, "1"),
        pin("sizeScale", "float", false, "1"), pin("speedScale", "float", false, "1"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_GetEmitterState", "Get Emitter State", "Particles", {
        pin("entity", "int", false), pin("alive", "int", true), pin("onGpu", "bool", true), pin("found", "bool", true)}});
    t.push_back({"AN_GetParticleStats", "Get Particle Stats", "Particles", {
        pin("gpuEmitters", "int", true), pin("cpuEmitters", "int", true), pin("gpuParticles", "int", true),
        pin("cpuParticles", "int", true), pin("ok", "bool", true)}});
}
